/* settings, touch controls and editor */
canvas{touch-action:none}
.gear{width:34px;height:34px;border:1px solid #f1d7a866;background:#10272544;border-radius:3px;color:#f6e8ca;font-size:16px;line-height:1;display:grid;place-items:center;cursor:pointer;pointer-events:auto;transition:.2s;padding:0}
.gear:hover{background:#1d3a34aa;border-color:#ffe7ac;transform:rotate(35deg)}
.panel-overlay{position:fixed;inset:0;z-index:20;background:rgba(3,12,13,.62);backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);display:flex;align-items:center;justify-content:center;padding:22px;opacity:0;pointer-events:none;transition:opacity .25s}
.panel-overlay.open{opacity:1;pointer-events:auto}
.panel{width:min(560px,100%);max-height:88vh;overflow:auto;background:linear-gradient(160deg,#0e2421f5,#091715fa);border:1px solid #e8c98b66;box-shadow:0 24px 70px #000a,inset 0 1px 0 #fff2;padding:22px 24px 18px;transform:translateY(12px);transition:transform .3s;scrollbar-width:thin;scrollbar-color:#e8c98b55 transparent}
.panel-overlay.open .panel{transform:none}
.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px}
.panel-title{font:600 17px Cinzel,serif;letter-spacing:2.5px;color:#fff2d6}
