document.getElementById('skillDash').addEventListener('click',galeStep);document.getElementById('skillBurst').addEventListener('click',tempest);document.getElementById('skillAttack').addEventListener('click',()=>attack());renderer.domElement.addEventListener('click',()=>{if(active&&!settingsOpen&&performance.now()>suppressClickUntil)attack()});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
// Drag to turn the camera, with smooth follow. Touch drags look; a tap slashes.
let dragging=false,lastX=0;
renderer.domElement.addEventListener('pointerdown',e=>{
  if(e.pointerType==='touch'){
    touchLook={id:e.pointerId,x:e.clientX,y:e.clientY};touchMoved=0;
    try{renderer.domElement.setPointerCapture(e.pointerId)}catch(err){}
    return;
  }
  if(e.button===2){dragging=true;lastX=e.clientX}
});
function endPointer(e){
  if(touchLook&&e.pointerId===touchLook.id){
    const tap=touchMoved<10;touchLook=null;suppressClickUntil=performance.now()+450;
    if(tap&&active&&!settingsOpen)attack();
  }
  dragging=false;
}
window.addEventListener('pointerup',endPointer);
window.addEventListener('pointercancel',endPointer);
window.addEventListener('pointermove',e=>{
  if(touchLook&&e.pointerId===touchLook.id){
    const dx=e.clientX-touchLook.x,dy=e.clientY-touchLook.y;
    yaw-=dx*.006*settings.sens;touchMoved+=Math.abs(dx)+Math.abs(dy);
    touchLook.x=e.clientX;touchLook.y=e.clientY;return;
  }
  if(dragging){yaw-=(e.clientX-lastX)*.006*settings.sens;lastX=e.clientX}
});

